public class HighestSale {
    public static void main(String[] args) {
        int[] sales = {-4, -2, -9};
        int highest = sales[0];
        for (int i = 1; i < sales.length; i++) {
            if (sales[i] > highest) {
                highest = sales[i];
            }
        }
        System.out.println(highest);
    }
}

